# Atchison & Dirette - Conditions in Occupational Therapy: Effect on Occupational Performance (Wolters Kluwer).
# Chapter list supplied by the site owner (not verified against the publisher). Summaries are written for this site.

def ch(n, title, text, keys):
    return (n, title, [text], keys)

C = [
    ch(1, "Neurodevelopmental Disorders (Autism Spectrum Disorder, Intellectual Disability)", "Autism spectrum disorder involves differences in social communication and restricted, repetitive behaviors, often with sensory processing differences. Intellectual disability involves limits in intellectual and adaptive functioning beginning in childhood. OT supports play, self-care, sensory regulation, and participation.", ["Social communication", "Sensory processing", "Adaptive functioning", "Participation"]),
    ch(2, "Attention-Deficit/Hyperactivity Disorder (ADHD)", "ADHD involves inattention and/or hyperactivity-impulsivity that affect school, home, and social life. OT uses routines, organization strategies, environmental changes, and sensory strategies to improve function.", ["Inattention", "Hyperactivity-impulsivity", "Organization strategies", "Routines"]),
    ch(3, "Cerebral Palsy", "Cerebral palsy is a non-progressive movement disorder from early brain injury; types include spastic (most common), dyskinetic, and ataxic. OT focuses on positioning, motor skills, adaptive equipment, and ADL independence.", ["Non-progressive", "Spastic type most common", "Positioning", "Adaptive equipment"]),
    ch(4, "Muscular Dystrophy", "Muscular dystrophies are genetic disorders causing progressive muscle weakness; Duchenne (X-linked) is most common in boys and shows Gowers sign. OT addresses energy conservation, mobility, and adaptive equipment as abilities change.", ["Progressive weakness", "Duchenne (X-linked)", "Gowers sign", "Energy conservation"]),
    ch(5, "Cerebrovascular Accident (Stroke)", "A stroke interrupts blood flow to the brain (ischemic or hemorrhagic), causing hemiplegia, aphasia, neglect, and cognitive changes. OT includes retraining ADLs, one-handed techniques, constraint-induced movement therapy, and addressing unilateral neglect.", ["Hemiplegia", "Unilateral neglect", "Constraint-induced therapy", "One-handed techniques"]),
    ch(6, "Traumatic Brain Injury (TBI)", "TBI ranges from concussion to severe injury and affects cognition, behavior, and motor skills. The Rancho Los Amigos scale describes recovery levels. OT addresses cognition, safety, and daily routines.", ["Rancho Los Amigos scale", "Cognitive deficits", "Behavior changes", "Safety"]),
    ch(7, "Spinal Cord Injury (SCI)", "SCI causes loss of function below the injury level: tetraplegia (cervical) or paraplegia (thoracic and below), complete or incomplete. Autonomic dysreflexia is an emergency in injuries at T6 and above. OT uses adaptive equipment and tenodesis grasp training.", ["Tetraplegia vs. paraplegia", "Complete vs. incomplete", "Autonomic dysreflexia", "Tenodesis grasp"]),
    ch(8, "Multiple Sclerosis", "MS is an autoimmune disease damaging myelin in the central nervous system, with relapsing or progressive courses. Symptoms include fatigue, weakness, vision changes, and heat sensitivity. OT teaches energy conservation and heat avoidance.", ["Demyelination", "Fatigue", "Heat sensitivity", "Energy conservation"]),
    ch(9, "Parkinson's Disease", "Parkinson's results from loss of dopamine-producing neurons, causing tremor, rigidity, bradykinesia, and postural instability. OT uses large-amplitude movements, cueing for freezing, and fall prevention.", ["Dopamine loss", "Tremor, rigidity, bradykinesia", "Cueing", "Fall prevention"]),
    ch(10, "Amyotrophic Lateral Sclerosis (ALS) and Guillain-Barré Syndrome", "ALS is a progressive disease of motor neurons leading to paralysis; OT focuses on adaptive equipment and communication devices. Guillain-Barré is an acute autoimmune neuropathy with ascending weakness; most people recover with rehabilitation.", ["ALS progressive", "Guillain-Barré ascending weakness", "Communication devices", "Recovery in GBS"]),
    ch(11, "Neurocognitive Disorders (Alzheimer's Disease and Dementia)", "Dementia causes progressive decline in memory and thinking; Alzheimer's is most common. OT simplifies tasks, uses cues and routines, modifies the environment for safety, and supports caregivers. Allen Cognitive Levels guide interventions.", ["Progressive decline", "Simplify tasks", "Environmental safety", "Caregiver support"]),
    ch(12, "Mood and Anxiety Disorders", "Depression and bipolar disorder affect mood, energy, and motivation; anxiety disorders cause excessive worry and avoidance. OT uses meaningful activity, routines, coping skills, and graded participation.", ["Depression", "Bipolar disorder", "Anxiety", "Meaningful routines"]),
    ch(13, "Schizophrenia and Psychotic Disorders", "Schizophrenia involves positive symptoms (hallucinations, delusions) and negative symptoms (flat affect, low motivation). OT supports life skills, social skills, routines, and community living.", ["Positive vs. negative symptoms", "Life skills", "Social skills", "Community living"]),
    ch(14, "Substance-Related and Addictive Disorders", "Substance use disorders involve compulsive use despite harm. OT helps build healthy routines, leisure, coping skills, and vocational skills that support recovery.", ["Compulsive use", "Healthy routines", "Leisure exploration", "Recovery support"]),
    ch(15, "Orthopedic Conditions (Fractures, Joint Replacements, Amputations)", "Fractures, joint replacements (hip precautions), and amputations affect mobility and ADLs. OT teaches adaptive techniques, uses assistive devices (reachers, sock aids), and supports prosthetic training.", ["Hip precautions", "Assistive devices", "Prosthetic training", "ADL retraining"]),
    ch(16, "Arthritis (Osteoarthritis and Rheumatoid Arthritis)", "Osteoarthritis is degenerative wear; rheumatoid arthritis is autoimmune with symmetrical joint inflammation and deformities (ulnar drift, swan neck, boutonnière). OT uses joint protection, splints, and energy conservation.", ["OA vs. RA", "Joint deformities", "Joint protection", "Splinting"]),
    ch(17, "Burns", "Burns are classified by depth (superficial, partial-thickness, full-thickness) and extent (rule of nines). OT focuses on positioning and splinting to prevent contractures, scar management with pressure garments, and ADLs.", ["Burn depth", "Rule of nines", "Prevent contractures", "Pressure garments"]),
    ch(18, "Cardiac and Pulmonary Conditions", "Heart disease and COPD limit endurance. OT monitors vital signs and exertion, teaches energy conservation, pursed-lip breathing, and work simplification, and supports cardiac and pulmonary rehab.", ["Monitor vitals", "Energy conservation", "Pursed-lip breathing", "Work simplification"]),
    ch(19, "Diabetes Mellitus", "Diabetes affects blood sugar regulation and can cause neuropathy, vision loss, and amputations. OT supports self-management routines, foot care, low-vision adaptations, and safe activity.", ["Self-management", "Neuropathy", "Foot care", "Low vision"]),
    ch(20, "Oncology (Cancer)", "Cancer and its treatment cause fatigue, pain, lymphedema, and cognitive changes ('chemo brain'). OT addresses energy conservation, lymphedema management, and returning to valued roles.", ["Cancer-related fatigue", "Lymphedema", "Chemo brain", "Return to roles"]),
    ch(21, "HIV/AIDS", "HIV attacks the immune system; with treatment, people live long lives but may experience fatigue, neuropathy, and cognitive changes. OT supports energy management, routines, and participation; standard precautions apply.", ["Immune suppression", "Fatigue", "Neuropathy", "Standard precautions"]),
    ch(22, "Low Vision and Hearing Loss", "Low vision (e.g., macular degeneration, glaucoma) and hearing loss affect safety and communication. OT uses magnifiers, lighting, contrast, organization, and communication strategies.", ["Magnifiers and lighting", "Contrast", "Communication strategies", "Home safety"]),
]

